#!/usr/bin/env node
// Prepares the built site (public/) for the Infomaniak web hosting (Apache + PHP).
// Run after the Hugo build:  node hosting/infomaniak/build.js
//
// - public/.htaccess = htaccess.base + the redirects of deuxfleurs.toml (regenerated by Osuny)
// - public/contact.php = contact form endpoint
//
// These files are not in static/ on purpose: on the current Deuxfleurs hosting,
// contact.php would be served as plain text.

const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '../..')
const publicDir = path.resolve(root, process.argv[2] || 'public')

if (!fs.existsSync(publicDir)) {
  console.error(`No ${publicDir}: build the site with Hugo first.`)
  process.exit(1)
}

// Redirects from deuxfleurs.toml: blocks [[redirects]] with from = "…" / to = "…" (/ status = 302)
const parseRedirects = (toml) => {
  const redirects = []
  for (const block of toml.split(/^\[\[/m).slice(1)) {
    if (!block.startsWith('redirects]]')) continue
    const get = (key) => (block.match(new RegExp(`^${key}\\s*=\\s*"?([^"\\n]+)"?\\s*$`, 'm')) || [])[1]
    const from = get('from')
    const to = get('to')
    if (from && to) redirects.push({ from, to, status: get('status') || '301' })
  }
  return redirects
}

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

// "/a/b/index.html" -> matches /a/b, /a/b/ and /a/b/index.html
const toRule = ({ from, to, status }) => {
  let pattern = from.replace(/^\//, '')
  if (pattern.endsWith('index.html')) {
    pattern = escapeRegex(pattern.slice(0, -'index.html'.length).replace(/\/$/, ''))
    pattern = pattern ? `^${pattern}/?(index\\.html)?$` : '^(index\\.html)?$'
  } else {
    pattern = `^${escapeRegex(pattern)}$`
  }
  return `  RewriteRule ${pattern} ${to.replace(/ /g, '%20')} [R=${status},L,NE]`
}

const toml = fs.readFileSync(path.join(root, 'deuxfleurs.toml'), 'utf8')
const redirects = parseRedirects(toml)
const base = fs.readFileSync(path.join(__dirname, 'htaccess.base'), 'utf8')

const htaccess = `${base}
# Redirects (generated from deuxfleurs.toml, managed by Osuny)
<IfModule mod_rewrite.c>
  RewriteEngine On
${redirects.map(toRule).join('\n')}
</IfModule>
`

fs.writeFileSync(path.join(publicDir, '.htaccess'), htaccess)
fs.copyFileSync(path.join(__dirname, 'contact.php'), path.join(publicDir, 'contact.php'))

console.log(`public/.htaccess: ${redirects.length} redirects`)
console.log('public/contact.php: copied')
